import React, { useState, useEffect } from 'react';
import { 
  Container, 
  Typography, 
  Card, 
  CardContent, 
  Grid,
  Box,
  IconButton,
  Tooltip,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper
} from '@material-ui/core';
import { makeStyles } from '@material-ui/core/styles';
import PendingIcon from '@material-ui/icons/History';
import wordApi from 'apis/wordApi';

const useStyles = makeStyles((theme) => ({
  root: {
    padding: theme.spacing(3),
  },
  table: {
    minWidth: 650,
  },
  wordTitle: {
    fontWeight: 600,
    color: theme.palette.primary.main,
  },
  pending: {
    color: theme.palette.warning.main,
  },
}));

function WordManagement() {
  const classes = useStyles();
  const [approvedWords, setApprovedWords] = useState([]);

  useEffect(() => {
    loadApprovedWords();
  }, []);

  const loadApprovedWords = async () => {
    try {
      const response = await wordApi.getApprovedWords();
      const words = response?.data?.list || [];
      setApprovedWords(words);
    } catch (error) {
      console.error('Failed to load approved words:', error);
      setApprovedWords([]);
    }
  };

  const handleSetToPending = async (wordId) => {
    try {
      await wordApi.setWordToPending(wordId);
      loadApprovedWords(); // Reload the list
    } catch (error) {
      console.error('Failed to set word to pending:', error);
    }
  };

  return (
    <Container className={classes.root}>
      <Typography variant="h4" gutterBottom>
        Word Management
      </Typography>

      <TableContainer component={Paper}>
        <Table className={classes.table}>
          <TableHead>
            <TableRow>
              <TableCell>Word</TableCell>
              <TableCell>Type</TableCell>
              <TableCell>Level</TableCell>
              <TableCell>Specialty</TableCell>
              <TableCell>Meaning</TableCell>
              <TableCell>Actions</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {approvedWords.map((word) => (
              <TableRow key={word._id}>
                <TableCell className={classes.wordTitle}>{word.word}</TableCell>
                <TableCell>{word.type}</TableCell>
                <TableCell>{word.level}</TableCell>
                <TableCell>{word.specialty}</TableCell>
                <TableCell>{word.mean}</TableCell>
                <TableCell>
                  <Tooltip title="Set to Pending">
                    <IconButton 
                      onClick={() => handleSetToPending(word._id)}
                      className={classes.pending}
                    >
                      <PendingIcon />
                    </IconButton>
                  </Tooltip>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>

      {approvedWords.length === 0 && (
        <Typography variant="body1" align="center" style={{ marginTop: 20 }}>
          No approved words found
        </Typography>
      )}
    </Container>
  );
}

export default WordManagement;
